@startuml

class Department {
  + name : string
  + location : string
}

class ResearchGroup {
  + groupName : string
  + description : string
}

class Researcher {
  + researcherId : int
  + name : string
  + email : string
}

class Project {
  + projectId : int
  + title : string
  + budget : float
}

class WorkPackage {
  + wpId : int
  + wpName : string
  + status : string
}

class Assignment {
  + assignmentDate : date
  + role : string
}

Department "1" -- "1..*" ResearchGroup
ResearchGroup "1" -- "1..*" Researcher
ResearchGroup "1" -- "1..*" WorkPackage : leads
Project "1" *-- "1..*" WorkPackage
WorkPackage "1" -- "1..*" Researcher : includes
WorkPackage "1" -- "1..*" Assignment
Researcher "1" -- "1..*" Assignment
Assignment "1" -- "1" WorkPackage
Assignment "1" -- "1" Researcher

@enduml

